from __future__ import annotations

from pathlib import Path
from typing import List, Optional, Text

from rasa.exceptions import ValidationError
from rasa.shared.constants import DEFAULT_CONFIG_PATH
from rasa.shared.engine_version import (
    CALM_ENGINE_VERSION,
    MANTLE_ENGINE_VERSION,
)

CALM_DOMAIN_FILE = "domain.yml"
MANTLE_AGENT_FILE = "agent.yml"
MANTLE_INTEGRATIONS_FILE = "integrations.yml"
MANTLE_MEMORY_FILE = "memory.yml"
MANTLE_SKILLS_DIR = "skills"
MANTLE_SKILL_FILE = "skill.md"
MANTLE_REFERENCES_DIR = "references"
MANTLE_SNAPSHOT_DIR = "mantle_snapshot"


def _find_mantle_skill_files(project_root: Path) -> List[Path]:
    """Return loadable ``skills/<id>/skill.md`` files under *project_root*.

    Directories whose names start with ``_`` are scratch directories and are
    skipped, matching the skill catalog. A directory named ``skill.md`` does
    not count; the catalog only loads a ``skill.md`` file.
    """
    skills_root = project_root / MANTLE_SKILLS_DIR
    if not skills_root.is_dir():
        return []

    return sorted(
        skill_file
        for skill_file in skills_root.glob(f"*/{MANTLE_SKILL_FILE}")
        if skill_file.is_file() and not skill_file.parent.name.startswith("_")
    )


def _mixed_layout_error(project_root: Path) -> ValidationError:
    """Return the error for a directory that mixes CALM and Mantle files."""
    return ValidationError(
        code="config.project_structure.mixed_layout",
        event_info=(
            f"Detected mixed CALM and Mantle project layouts under "
            f"'{project_root}'. A Mantle project has "
            f"'{MANTLE_AGENT_FILE}', '{MANTLE_INTEGRATIONS_FILE}', and "
            f"'{MANTLE_SKILLS_DIR}/<id>/{MANTLE_SKILL_FILE}'. To use Mantle, "
            f"remove any CALM files such as '{CALM_DOMAIN_FILE}'."
        ),
    )


def has_mantle_project_layout(project_root: Path) -> bool:
    """Return whether *project_root* is a Mantle project layout.

    At least two of ``agent.yml``, ``integrations.yml``, and a
    ``skills/<id>/skill.md`` file must be present. A ``skills/`` directory
    with no ``skill.md``, and a skill directory whose name starts with ``_``,
    do not count.
    """
    has_agent_file = (project_root / MANTLE_AGENT_FILE).is_file()
    has_integrations_file = (project_root / MANTLE_INTEGRATIONS_FILE).is_file()
    has_skill_file = bool(_find_mantle_skill_files(project_root))
    marker_count = sum((has_agent_file, has_integrations_file, has_skill_file))
    return marker_count >= 2


def validate_mantle_project_structure(project_root: Path) -> None:
    """Raise when a Mantle layout is mixed with CALM or missing files.

    No-op when *project_root* is not a Mantle layout. Checks run in order:
    a CALM ``domain.yml``, a missing ``agent.yml``, then no ``skill.md`` files.

    Raises:
        ValidationError: ``config.project_structure.mixed_layout``,
            ``config.project_structure.missing_agent_yml``, or
            ``config.project_structure.missing_skills``.
    """
    root = Path(project_root)
    if not has_mantle_project_layout(root):
        return

    if (root / CALM_DOMAIN_FILE).is_file():
        raise _mixed_layout_error(root)

    if not (root / MANTLE_AGENT_FILE).is_file():
        raise ValidationError(
            code="config.project_structure.missing_agent_yml",
            event_info=(
                f"Detected a Mantle project under '{root}' but "
                f"'{MANTLE_AGENT_FILE}' is missing. Add '{MANTLE_AGENT_FILE}' at the "
                f"project root (do not use '{DEFAULT_CONFIG_PATH}' for Mantle)."
            ),
        )

    if not _find_mantle_skill_files(root):
        raise ValidationError(
            code="config.project_structure.missing_skills",
            event_info=(
                f"Detected a Mantle project under '{root}' but no skills were "
                f"found. Add at least one skill at "
                f"'{MANTLE_SKILLS_DIR}/<id>/{MANTLE_SKILL_FILE}'."
            ),
        )


def resolve_project_config_path(
    config: Optional[Text] = None,
    *,
    project_root: Optional[Path | str] = None,
) -> Optional[Text]:
    """Return the on-disk project config path for the detected layout.

    Mantle projects always use ``agent.yml`` — ``config.yml`` is
    ignored even when present. CALM projects use ``config.yml``.

    A config file that lives in a different directory is checked against that
    directory too, so ``--config /other/agent.yml`` from another working
    directory still raises when ``/other`` is a Mantle layout missing skills.
    When that directory is a Mantle layout, the returned path is its
    ``agent.yml``, even if the requested file was ``config.yml``.

    Raises:
        ValidationError: When the working directory, or the directory that
            contains an explicit config file, is a Mantle layout mixed with
            ``domain.yml``, missing ``agent.yml``, or missing every
            ``skills/<id>/skill.md``.
    """
    root = Path(project_root or Path.cwd()).resolve()
    validate_mantle_project_structure(root)

    if has_mantle_project_layout(root):
        return str(root / MANTLE_AGENT_FILE)

    requested = config or DEFAULT_CONFIG_PATH
    requested_path = Path(requested)
    if not requested_path.is_absolute():
        requested_path = root / requested_path

    if requested_path.is_file():
        config_project = requested_path.parent.resolve()
        if config_project != root:
            validate_mantle_project_structure(config_project)
            if has_mantle_project_layout(config_project):
                return str(config_project / MANTLE_AGENT_FILE)
        return str(requested_path)

    if requested != DEFAULT_CONFIG_PATH:
        return None

    legacy_config = root / DEFAULT_CONFIG_PATH
    if legacy_config.is_file():
        return str(legacy_config)

    return None


def resolve_engine_version_from_project(project_root: Path | str) -> str:
    """Resolve engine version from project file layout.

    A Mantle layout (at least two of ``agent.yml``, ``integrations.yml``,
    and ``skills/<id>/skill.md``) resolves to
    :data:`~rasa.shared.engine_version.MANTLE_ENGINE_VERSION`.
    A mixed CALM and Mantle layout raises :class:`~rasa.exceptions.ValidationError`.
    Anything else resolves to
    :data:`~rasa.shared.engine_version.CALM_ENGINE_VERSION`.
    """
    root = Path(project_root).resolve()
    has_calm_signature = (root / CALM_DOMAIN_FILE).is_file()
    has_mantle_signature = has_mantle_project_layout(root)

    if has_calm_signature and has_mantle_signature:
        raise _mixed_layout_error(root)

    if has_mantle_signature:
        return MANTLE_ENGINE_VERSION

    return CALM_ENGINE_VERSION


def validate_project_structure_for_engine_version(
    config_path: Text, engine_version: Text | None = None
) -> str:
    """Validate project layout and return the layout-resolved engine version.

    *engine_version* is accepted for call-site compatibility but ignored —
    layout is authoritative.

    Raises:
        ValidationError: When the layout is mixed, or a Mantle layout has no
            ``agent.yml`` or no ``skills/<id>/skill.md``.
    """
    del engine_version  # layout is the source of truth
    root = Path(config_path).resolve().parent
    engine_version_from_layout = resolve_engine_version_from_project(root)
    validate_mantle_project_structure(root)
    return engine_version_from_layout
